16	#ifndef TENSORFLOW_CORE_GRAPPLER_OPTIMIZERS_CONSTANT_FOLDING_H_
17	#define TENSORFLOW_CORE_GRAPPLER_OPTIMIZERS_CONSTANT_FOLDING_H_
18	
19	#include "absl/container/flat_hash_map.h"
20	#include "absl/container/flat_hash_set.h"
21	#include "absl/types/span.h"
22	#include "tensorflow/core/framework/device_base.h"
23	#include "tensorflow/core/framework/op_kernel.h"
24	#include "tensorflow/core/framework/resource_mgr.h"
25	#include "tensorflow/core/framework/tensor_shape.pb.h"
26	#include "tensorflow/core/grappler/costs/graph_properties.h"
27	#include "tensorflow/core/grappler/optimizers/graph_optimizer.h"
28	#include "tensorflow/core/grappler/utils.h"
29	#include "tensorflow/core/protobuf/rewriter_config.pb.h"
30	
31	namespace tensorflow {
32	namespace grappler {
33	
34	const char kConstantFoldingConst[] = "ConstantFolding";
35	const char kConstantFoldingCtrl[] = "ConstantFoldingCtrl";
36	extern const int64_t kMaxConstantSize;
37	
38	// Constant folding optimization for a graph.
39	class ConstantFolding : public GraphOptimizer {
40	 public:
41	  // The size limit will only be considered if the newly created node is greater
42	  // than original_size (optional).
43	  static absl::Status CreateNodeDef(const std::string& name,
44	                                    const TensorValue& tensor, NodeDef* node,
45	                                    size_t original_size = 0);
46	  static std::string AddControlDependency(const std::string& input_name,
47	                                          GraphDef* graph, NodeMap* node_map);
48	
49	  explicit ConstantFolding(DeviceBase* cpu_device,
50	                           bool disable_compressed_tensor_optimization = false,
51	                           bool fold_quantization_emulation = true);
52	  ConstantFolding(RewriterConfig::Toggle opt_level, DeviceBase* cpu_device,
53	                  bool disable_compressed_tensor_optimization = false,
54	                  bool fold_quantization_emulation = true);
55	
56	  ~ConstantFolding() override {}
57	
58	  std::string name() const override { return "constant_folding"; };
59	
60	  bool UsesFunctionLibrary() const override { return false; }
61	
62	  absl::Status Optimize(Cluster* cluster, const GrapplerItem& item,
63	                        GraphDef* output) override;
64	
65	 private:
66	  bool ForwardInputs(NodeDef* node, absl::Span<const int> inputs_to_forward);
67	  std::string OptimizedNodeName(const NodeDef& node,
68	                                absl::string_view suffix) const;
69	  bool OptimizedNodeExists(const NodeDef& node, absl::string_view suffix) const;
70	
71	  bool IsReallyConstant(const NodeDef& node) const;
72	
73	  bool GetTensorFromConstNode(const std::string& node_name_or_input,
74	                              Tensor* tensor);
75	
76	  absl::Status MaterializeShapes(const GraphProperties& properties);
77	
78	  absl::Status MaterializeBroadcastGradientArgs(
79	      const NodeDef& node, const GraphProperties& properties);
80	  absl::Status MaterializeReductionIndices(NodeDef* node,
81	                                           const GraphProperties& properties);
82	  absl::Status MaterializeConstantValuedNode(NodeDef* node,
83	                                             const GraphProperties& properties);
84	  absl::Status MaterializeOutputValues(NodeDef* node,
85	                                       const GraphProperties& properties);
86	  absl::Status MaterializeConstants(const GraphProperties& properties);
87	
88	  bool IsFoldable(const NodeDef& node, const GraphProperties* properties);
89	  bool IsFoldableUncached(const NodeDef& node,
90	                          const GraphProperties* properties) const;
91	  bool MaybeFoldable(const NodeDef& node,
92	                     const GraphProperties* properties) const;
93	
94	  absl::Status EvaluateNode(
95	      const NodeDef& node, const absl::InlinedVector<TensorValue, 4UL>& inputs,
96	      absl::InlinedVector<TensorValue, 4UL>* output) const;
97	
98	  absl::Status EvaluateOneFoldable(const NodeDef& node,
99	                                   std::vector<NodeDef>* outputs,
100	                                   bool* result_too_large);
101	
102	  absl::Status FoldMergeNode(NodeDef* node, GraphDef* output_graph);
103	  absl::Status FoldNode(NodeDef* node, GraphDef* output_graph,
104	                        bool* result_too_large);
105	
106	  bool IsOnes(const NodeDef& node) const;
107	  bool IsZeros(const NodeDef& node) const;
108	  bool ReplaceOperationWithBroadcastTo(int input_to_broadcast,
109	                                       const GraphProperties& properties,
110	                                       NodeDef* node, GraphDef* graph);
111	  void ReplaceOperationWithIdentity(int input_to_forward,
112	                                    const GraphProperties& properties,
113	                                    NodeDef* node, GraphDef* graph);
114	  void ReplaceOperationWithSnapshot(int input_to_forward,
115	                                    const GraphProperties& properties,
116	                                    NodeDef* node, GraphDef* graph);
117	  void ReplaceOperationWithNoOp(NodeDef* node, GraphProperties* properties,
118	                                GraphDef* graph);
119	  void ReplaceBinaryOperationWithBroadcastTo(int input_to_broadcast,
120	                                             const GraphProperties& properties,
121	                                             NodeDef* node, GraphDef* graph);
122	  void ReplaceSubtractionFromZeroByNegation(NodeDef* node, GraphDef* graph);
123	  absl::Status ReplaceOperationWithConstant(double value,
124	                                            const GraphProperties& properties,
125	                                            const TensorShapeProto& shape,
126	                                            NodeDef* node, GraphDef* graph);
127	
128	  // Notice: Destroys *value.
129	  absl::Status ReplaceOperationWithConstantTensor(DataType dtype,
130	                                                  TensorProto* value,
131	                                                  NodeDef* node,
132	                                                  GraphDef* graph);
133	
134	  void ReplaceDivisionOfOnesByReciprocal(NodeDef* node, GraphDef* graph);
135	  absl::Status FoldGraph(
136	      const GraphProperties& properties, GraphDef* output,
137	      absl::flat_hash_set<std::string>* nodes_to_not_simplify);
138	
139	  absl::Status IsSimplifiableReshape(const NodeDef& node,
140	                                     const GraphProperties& properties) const;
141	  absl::Status SimplifyGraph(
142	      GraphDef* optimized_graph, GraphProperties* properties,
143	      absl::flat_hash_set<std::string>* nodes_to_not_simplify);
144	  absl::Status SimplifyNode(NodeDef* node, GraphDef* optimized_graph,
145	                            GraphProperties* properties);
146	
147	  absl::Status RunOptimizationPass(Cluster* cluster, GrapplerItem* item,
148	                                   GraphProperties* properties,
149	                                   GraphDef* optimized_graph);
150	
151	  // Applies partial constant folding for Concat which is not commutative.
152	  // Returns true if the transformation applied successfully.
153	  bool PartialConcatConstFolding(GraphDef* optimized_graph,
154	                                 GraphProperties* properties, NodeDef* node);
155	
156	  // Applies partial constant folding for associative operators AddN and
157	  // AccumulateNV2. Returns true if the transformation applied successfully.
158	  bool PartialAssocOpConstFolding(GraphDef* optimized_graph,
159	                                  GraphProperties* properties, NodeDef* node);
160	
161	  // Applies partial constant propagation through IdentityN operator.
162	  // Returns true if the transformation applied successfully.
163	  bool PartialConstPropThroughIdentityN(NodeDef* node);
164	
165	  struct ConstantPushDownContext {
166	    NodeDef* op_child;
167	    NodeDef* const_child;
168	    bool left_child_is_const;
169	    bool right_child_is_const;
170	    NodeDef* left_leaf;
171	    NodeDef* right_leaf;
172	    bool left_leaf_is_const;
173	    bool right_leaf_is_const;
174	
175	    // Shape & type information.
176	    const std::vector<OpInfo::TensorProperties>* parent_input_props;
177	    const std::vector<OpInfo::TensorProperties>* op_child_input_props;
178	  };
179	
180	  // Populates ctx with pointers to the nodes in expression tree for which
181	  // constant pushdown optimization is being considered, corresponding to one of
182	  // the following configurations:
183	  //
184	  //               parent                            parent
185	  //               /    \                            /    \
186	  //        op_child   const_child            const_child op_child
187	  //         /     \                                       /     \
188	  //    left_leaf  right_leaf                        left_leaf  right_leaf
189	  //
190	  // Returns true if the expression is possible amenable for optimization.
191	  // Returns false if must_have_properties is true and input properties for
192	  // parent and op_child are not known.
193	  bool PrepareConstantPushDown(const NodeDef& parent,
194	                               const GraphProperties& properties,
195	                               bool must_have_properties,
196	                               ConstantPushDownContext* ctx) const;
197	
198	  // Pushes down constants on '+', '-', '*', and '/' operators if applicable.
199	  // Returns true if the transformation applied successfully.
200	  bool ConstantPushDown(GraphProperties* properties, GraphDef* optimized_graph,
201	                        NodeDef* node);
202	
203	  // Pushes down constants on '+' and 'BiasAdd' operators if applicable.
204	  // Returns true if the graph was modified.
205	  bool ConstantPushDownBiasAdd(GraphProperties* properties,
206	                               GraphDef* optimized_graph, NodeDef* node);
207	
208	  // Aggregate constants present around a conv operator. Returns true if the
209	  // transformation was applied successfully.
210	  bool MulConvPushDown(GraphDef* optimized_graph, NodeDef* node,
211	                       const GraphProperties& properties);
212	
213	  // Strength reduces floating point division by a constant Div(x, const) to
214	  // multiplication by the reciprocal Mul(x, Reciprocal(const)).
215	  bool ReduceDivToReciprocalMul(GraphDef* optimized_graph, NodeDef* node);
216	
217	  // Simplifies arithmetic operations with ones or zeros. Returns the status,
218	  // and updates the success input argument that denotes if any simplification
219	  // was applied.
220	  absl::Status SimplifyArithmeticOperations(const GraphProperties& properties,
221	                                            bool use_shape_info,
222	                                            GraphDef* optimized_graph,
223	                                            NodeDef* node);
224	
225	  // Simplifies a Reshape operation to an Identity operation if applicable.
226	  bool SimplifyReshape(const GraphProperties& properties, bool use_shape_info,
227	                       NodeDef* node);
228	
229	  // Returns true iff the node is a reduction and its reduction indices are
230	  // constant. Sets *indices_is_empty to true if the set of dimensions to reduce
231	  // along is empty (this happens often in the gradient graphs).
232	  bool IsReductionWithConstantIndices(const NodeDef& node,
233	                                      bool* indices_is_empty) const;
234	  // Returns true if theres a possibility that a Reduce node could be simplified
235	  // to an Identity/Reshape.
236	  bool IsReductionCandidateForSimplification(
237	      const NodeDef& node, const GraphProperties& properties,
238	      TensorShapeProto* input_tensor_shape,
239	      TensorShapeProto* output_tensor_shape, bool* is_single_element_op) const;
240	  // Returns true iff this reduction can be reduced to an identity (i.e if the
241	  // input dimensions to reduce along are all of size 1 and keep_dims is true).
242	  bool IsReductionSimplifiableToIdentity(
243	      const NodeDef& node, const TensorShapeProto& input_shape, bool keep_dims,
244	      const absl::InlinedVector<TensorValue, 4UL>& reduction_indices_vector)
245	      const;
246	  // Changes a reduction into an Identity op, returning true on success.
247	  bool ReplaceReductionWithIdentity(NodeDef* node) const;
248	
249	  // Simplifies a Reduction operation to an Identity/Reshape operation if
250	  // applicable.
251	  bool SimplifyReduction(GraphDef* optimized_graph,
252	                         const GraphProperties& properties, NodeDef* node);
253	
254	  // Switch(x, x) will always feed false to its false branch and true to
255	  // its true branch. By rewriting the graph a bit, we can propagate these
256	  // constants down the two output branches, and just use control dependencies
257	  // to trigger the selected one at runtime. For example,
258	  //
259	  //     +------+
260	  // x-->|Switch|-->a  (in practice there may be multiple consumers of each
261	  // x-->|      |-->b   output branch.)
262	  //     +------+
263	  //
264	  // Is rewritten as
265	  //
266	  //     +------+
267	  // x-->|Switch|-->Identity--^>Const(false)-->a
268	  // x-->|      |-->Identity--^>Const(true)-->b
269	  //     +------+
270	  bool SimplifySwitch(GraphDef* optimized_graph, NodeDef* node);
271	
272	  // Moves constants past Enter node if applicable.
273	  bool MoveConstantsPastEnter(GraphDef* optimized_graph, NodeDef* node);
274	
275	  // Simplifies Pack operation if applicable.
276	  bool SimplifyPack(GraphDef* optimized_graph, NodeDef* node);
277	
278	  // Simplifies a Squeeze operation to an Identity operation if applicable.
279	  void SimplifySqueeze(const GraphProperties& properties, bool use_shape_info,
280	                       GraphDef* optimized_graph, NodeDef* node);
281	
282	  // Simplifies a Pad operation to an Identity operation if applicable.
283	  absl::Status SimplifyPad(const GraphProperties& properties,
284	                           bool use_shape_info, GraphDef* optimized_graph,
285	                           NodeDef* node);
286	
287	  // Simplifies a Tile operation to an Identity operation if applicable.
288	  absl::Status SimplifyTile(const GraphProperties& properties,
289	                            bool use_shape_info, GraphDef* optimized_graph,
290	                            NodeDef* node);
291	
292	  // Simplifies a StridedSlice operation to an Identity operation if applicable.
293	  absl::Status SimplifyStridedSlice(const GraphProperties& properties,
294	                                    bool use_shape_info,
295	                                    GraphDef* optimized_graph, NodeDef* node);
296	
297	  // Simplifies a Slice operation to an Identity operation if applicable.
298	  absl::Status SimplifySlice(const GraphProperties& properties,
299	                             bool use_shape_info, GraphDef* optimized_graph,
300	                             NodeDef* node);
301	
302	  // Simplify a Case operation where the output_idx is known.
303	  bool SimplifyCase(GraphDef* optimized_graph, NodeDef* node);
304	
305	  // Simplify a Select operation where the predicates are all true or all false.
306	  bool SimplifySelect(const GraphProperties& properties,
307	                      GraphDef* optimized_graph, NodeDef* node);
308	
309	  // Replaces variable updates that are effectively no-ops with NoOp nodes.
310	  void RemoveRedundantVariableUpdates(GraphProperties* properties,
311	                                      GraphDef* optimized_graph, NodeDef* node);
312	
313	  // Removes Reverse op over dimensions with size 1.
314	  absl::Status RemoveReverse(const GraphProperties& properties,
315	                             bool use_shape_info, GraphDef* optimized_graph,
316	                             NodeDef* node);
317	
318	  // Removes RandomShuffle op if it is scalar or first dimension is of size 1.
319	  void RemoveRandomShuffle(const GraphProperties& properties,
320	                           bool use_shape_info, GraphDef* optimized_graph,
321	                           NodeDef* node);
322	
323	  // Removes Shuffle or Transpose op over dimensions of size 1.
324	  absl::Status RemoveShuffleOrTranspose(const GraphProperties& properties,
325	                                        bool use_shape_info,
326	                                        GraphDef* optimized_graph,
327	                                        NodeDef* node);
328	
329	  // Removes Split or SplitV node if possible.
330	  void RemoveSplitOrSplitV(const GraphProperties& properties,
331	                           GraphDef* optimized_graph, NodeDef* node);
332	
333	  bool GetConcatAxis(const NodeDef& node, int* axis);
334	  bool MergeConcat(bool use_shape_info, GraphProperties* properties,
335	                   GraphDef* optimized_graph, NodeDef* node);
336	
337	  absl::Status AddQuantizedMatMulMinMaxOutConstNodes(NodeDef* node,
338	                                                     GraphDef* optimized_graph);
339	
340	  // Points to an externally provided device or to owned_device_;
341	  RewriterConfig::Toggle opt_level_;
342	  DeviceBase* cpu_device_;
343	  std::unique_ptr<DeviceBase> owned_device_;
344	
345	  std::unique_ptr<ResourceMgr> resource_mgr_;
346	  GraphDef* graph_;
347	  std::unique_ptr<NodeMap> node_map_;
348	  std::unordered_set<std::string> nodes_to_preserve_;
349	  // TODO(rmlarsen): Could these be keyed on absl::string_view?
350	  absl::flat_hash_set<std::string> nodes_allowlist_;
351	  absl::flat_hash_set<std::string> feed_nodes_;
352	  absl::flat_hash_map<std::string, bool> maybe_foldable_nodes_;
353	  bool has_fetch_;
354	  bool graph_modified_;
355	  bool graph_contains_assign_or_inplace_op_;
356	  bool disable_compressed_tensor_optimization_;
357	  bool fold_quantization_emulation_;
358	};
359	
360	}  // end namespace grappler
361	}  // end namespace tensorflow
362	
363	#endif  // TENSORFLOW_CORE_GRAPPLER_OPTIMIZERS_CONSTANT_FOLDING_H_
364

